     */
    public int membershipLevel(Integer householdSize) {
        int points = membershipPoints(householdSize);
        int level;
        if (points <= 1) {
            level = 1;
        }
        else if (points <= 3) {
            level = 2;
        }
        else if (points <= 5) {
            level = 3;
        }
        else {
